const message = $json;
const headers = message.payload?.headers ?? message.headers ?? [];
const header = (name) => headers.find((entry) => entry.name?.toLowerCase() === name.toLowerCase())?.value ?? null;
const decode = (value) => {
  if (!value) return null;
  const normalized = value.replace(/-/g, '+').replace(/_/g, '/');
  return Buffer.from(normalized, 'base64').toString('utf8');
};
const body = message.textPlain ?? message.text ?? decode(message.payload?.body?.data) ?? null;
const received = message.internalDate ? new Date(Number(message.internalDate)) : new Date(header('Date'));
if (!message.id || Number.isNaN(received.getTime())) {
  throw new Error('validation_error: Gmail message id or received date is missing');
}
return { json: {
  source: 'gmail',
  messageId: message.id,
  threadId: message.threadId ?? null,
  sender: header('From'),
  subject: header('Subject'),
  body,
  receivedAt: received.toISOString(),
} };
